function giSvg(name, color, cls) { const b = GICONS[name]; if (!b) return ''; return '<svg class="gi ' + (cls || '') + '" viewBox="0 0 512 512" aria-hidden="true"' + (color ? ' style="color:' + color + '"' : '') + '>' + b + '</svg>'; }
// Ikona dovednosti (SVG), záložně znak
function skillIcon(id, color) { const S = SKILLS[id]; return SKILL_ICONS[id] ? giSvg(SKILL_ICONS[id], color || (S && S.color)) : ('<span>' + (S ? S.glyph : '?') + '</span>'); }
// Barva pasivky podle bonusu
const STAT_COLORS = { firePct: '#ff8a3a', resFire: '#ff8a3a', ignite: '#ff8a3a', burnBonus: '#ff8a3a', frostPct: '#8fd8ff', resFrost: '#8fd8ff', slowPct: '#8fd8ff', slowAura: '#8fd8ff', freezeChance: '#8fd8ff', slowedBonus: '#8fd8ff', shatter: '#8fd8ff',
  shadowPct: '#c77dff', resShadow: '#c77dff', naturePct: '#8be07a', arcanePct: '#ff8cf0', eclipse: '#d8c0ff', dotPct: '#9be07a', dotDur: '#9be07a', dotSpread: '#9be07a', dottedBonus: '#9be07a', bleedHit: '#ff5050',
  hpPct: '#ff6b6b', ls: '#ff6b6b', regen: '#ff6b6b', healPct: '#7fe07f', killHeal: '#ff6b6b', lowHpDmg: '#ff5050', rebirth: '#fff2c0',
  def: '#b8c8dc', dmgRed: '#b8c8dc', block: '#b8c8dc', resAll: '#b8c8dc', dodge: '#b8c8dc', manaShield: '#b0a0ff', thorns: '#9be07a',
  petPct: '#e0b080', petSpd: '#e0b080', petLs: '#e0b080', petCount: '#e0b080', loneWolf: '#c0c0d0', formDur: '#e0b080',
  resMax: '#7fb0ff', resRegenPct: '#7fb0ff', genPct: '#ff7050', killRes: '#7fb0ff', critRes: '#7fb0ff', cdr: '#7fb0ff', skillPct: '#ff8cf0', goldPct: '#e0b030', dropPct: '#e0b030',
  enrageChance: '#ff4040', enrageDur: '#ff4040', enrageAlways: '#ff4040', vulnPct: '#ffb040' };

// Ikona uzlu talentového stromu
function nodeIconHtml(n) {
  if (n.type === 'key') return giSvg(KEY_ICONS[n.id] || 'sparkles', '#f0c040');
  if (n.skill || n.forSkill) return skillIcon(n.skill || n.forSkill);
  const st = n.type === 'choice' ? n.opts[0].stats : n.stats, k = Object.keys(st)[0] || '';
  const i = k.indexOf('_');
  if (i > 0) { const pre = k.slice(0, i), rest = k.slice(i + 1); if (pre.indexOf('sk') === 0 && SKILL_ICONS[rest]) return skillIcon(rest); return giSvg(STAT_ICONS[rest] || 'sparkles', STAT_COLORS[rest] || '#d8d0e8'); }
  return giSvg(STAT_ICONS[k] || 'sparkles', STAT_COLORS[k] || '#d8d0e8');
}

// Ikona jedné možnosti volby (podle toho, co dělá: plocha, počet, zmrazení …)
const OPT_KEY = { skd: 'critDmg', skr: 'auraPct', skc: 'primCount', skdur: 'dotDur', skcd: 'cdr', skcost: 'resMax', skgen: 'genPct', skpierce: 'primPierce',
  skstun: 'stunDmg', skslow: 'slowPct', skdot: 'dotPct', skheal: 'ls', skvuln: 'vulnPct', skburn: 'ignite', skbleed: 'bleedHit', skfreeze: 'freezeChance',
  skexec: 'execPct', skenrage: 'enrageAlways', skhits: 'doubleChance', skkillres: 'killRes' };
function optIconHtml(o, n) {
  const k = Object.keys(o.stats)[0] || '', i = k.indexOf('_');
  let key = k;
  if (i > 0) { const pre = k.slice(0, i); key = OPT_KEY[pre] || k.slice(i + 1); }
  const color = STAT_COLORS[key] || (n && n.forSkill ? SKILLS[n.forSkill].color : '#d8d0e8');
  return giSvg(STAT_ICONS[key] || 'sparkles', color);
}
